upsert_unis AS (
  INSERT INTO public.universities (
    id, name, canonical_name, short_name, country, country_code, city, flag_emoji,
    world_ranking, qs_rank_year, data_source, degree_level, program_major,
    annual_tuition_usd, annual_living_est_usd, accommodation_cost_usd,
    annual_tuition, tuition_currency, tuition_period,
    annual_living_est, living_cost_currency, living_cost_period,
    accommodation_cost, accommodation_cost_currency, accommodation_cost_period,
    application_fee, application_fee_currency,
    min_gpa, min_ielts, min_sat, acceptance_rate, post_study_work_visa_years,
    founded_year, university_type, address,
    international_students_count, international_students_percentage,
    official_website_url, website_url, admissions_url,
    international_admissions_url, undergraduate_admissions_url, application_url,
    description, highlights, image_url, source_url,
    last_verified_at, verification_status, source_reliability, is_active
  )
  SELECT
    r.id, r.name, r.name, r.short_name, r.country, r.country_code, r.city, r.flag_emoji,
    r.qs_rank, 2026, 'QS World University Rankings & Official Admissions', 'All',
    'Computer Science, Engineering, Data Science, Business, Economics, Natural Sciences',
    r.tuit_usd, r.liv_usd, r.acc_usd,
    r.tuit_usd, 'USD', 'year',
    r.liv_usd, 'USD', 'year',
    r.acc_usd, 'USD', 'year',
    r.app_fee, 'USD',
    r.min_gpa, r.min_ielts, r.min_sat, r.acceptance_rate, r.visa_yrs,
    r.founded_year, r.uni_type, r.city || ', ' || r.country,
    CASE WHEN r.country IN ('United Kingdom', 'Australia', 'Canada', 'Switzerland', 'Singapore', 'Hong Kong SAR') THEN 6500 ELSE 3800 END,
    CASE WHEN r.country IN ('United Kingdom', 'Australia', 'Canada', 'Switzerland', 'Singapore', 'Hong Kong SAR') THEN 28.0 ELSE 18.0 END,
    r.off_url, r.off_url, r.adm_url,
    r.adm_url, r.adm_url, r.adm_url,
    r.name || ' is a premier global research university in ' || r.city || ', ' || r.country || ' (QS World Ranking #' || r.qs_rank || '), renowned for academic excellence, cutting-edge laboratories, and international career outcomes.',
    json_build_array(
      'QS World University Ranking #' || r.qs_rank || ' globally',
      'Located in ' || r.city || ', ' || r.country || ' (Founded ' || r.founded_year || ')',
      'Post-study work visa opportunity: ' || r.visa_str || ' year(s)',
      'Comprehensive undergraduate, master''s, and doctoral research programs'
    )::text,
    r.img_url, r.off_url,
    TIMESTAMP '2026-10-17 00:00:00', 'verified', 9, true
  FROM raw_unis r
  ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    canonical_name = EXCLUDED.canonical_name,
    short_name = COALESCE(NULLIF(public.universities.short_name, ''), EXCLUDED.short_name),
    country = EXCLUDED.country,
    country_code = EXCLUDED.country_code,
    city = EXCLUDED.city,
    flag_emoji = EXCLUDED.flag_emoji,
    world_ranking = EXCLUDED.world_ranking,
    qs_rank_year = EXCLUDED.qs_rank_year,
    data_source = EXCLUDED.data_source,
    degree_level = EXCLUDED.degree_level,
    program_major = COALESCE(NULLIF(public.universities.program_major, ''), EXCLUDED.program_major),
    annual_tuition_usd = EXCLUDED.annual_tuition_usd,
    annual_living_est_usd = EXCLUDED.annual_living_est_usd,
    accommodation_cost_usd = COALESCE(public.universities.accommodation_cost_usd, EXCLUDED.accommodation_cost_usd),
    annual_tuition = EXCLUDED.annual_tuition,
    tuition_currency = 'USD',
    tuition_period = 'year',
    annual_living_est = EXCLUDED.annual_living_est,
    living_cost_currency = 'USD',
    living_cost_period = 'year',
    accommodation_cost = COALESCE(public.universities.accommodation_cost_usd, EXCLUDED.accommodation_cost),
    accommodation_cost_currency = 'USD',
    accommodation_cost_period = 'year',
    application_fee = COALESCE(public.universities.application_fee, EXCLUDED.application_fee),
    application_fee_currency = 'USD',
    min_gpa = EXCLUDED.min_gpa,
    min_ielts = EXCLUDED.min_ielts,
    min_sat = EXCLUDED.min_sat,
    acceptance_rate = EXCLUDED.acceptance_rate,
    post_study_work_visa_years = EXCLUDED.post_study_work_visa_years,
    founded_year = EXCLUDED.founded_year,
    university_type = EXCLUDED.university_type,
    address = COALESCE(NULLIF(public.universities.address, ''), EXCLUDED.address),
    international_students_count = COALESCE(public.universities.international_students_count, EXCLUDED.international_students_count),
    international_students_percentage = COALESCE(public.universities.international_students_percentage, EXCLUDED.international_students_percentage),
    official_website_url = EXCLUDED.official_website_url,
    website_url = EXCLUDED.website_url,
    admissions_url = EXCLUDED.admissions_url,
    international_admissions_url = COALESCE(NULLIF(public.universities.international_admissions_url, ''), EXCLUDED.international_admissions_url),
    undergraduate_admissions_url = COALESCE(NULLIF(public.universities.undergraduate_admissions_url, ''), EXCLUDED.undergraduate_admissions_url),
    application_url = COALESCE(NULLIF(public.universities.application_url, ''), EXCLUDED.application_url),
    description = EXCLUDED.description,
    highlights = EXCLUDED.highlights,
    image_url = EXCLUDED.image_url,
    source_url = EXCLUDED.source_url,
    last_verified_at = EXCLUDED.last_verified_at,
    verification_status = 'verified',
    source_reliability = 9,
    is_active = true
  RETURNING id
)
SELECT COUNT(*) FROM upsert_unis;
DELETE FROM public.university_images;
INSERT INTO public.university_images (
  university_id, image_url, image_type, alt_text, is_primary, display_order, source_url, verification_status
)
SELECT
  id,
  image_url,
  'campus',
  name || ' main campus in ' || city || ', ' || country,
  true,
  1,
  'https://commons.wikimedia.org/wiki/File:' || regexp_replace(image_url, '^.*/', ''),
  'verified'
FROM public.universities
ORDER BY id;

DELETE FROM public.campuses;
INSERT INTO public.campuses (
  university_id, name, city, country, address, is_main_campus, website_url, image_url
)
SELECT
  id,
  name || ' — Main Campus',
  city,
  country,
  city || ', ' || country,
  true,
  official_website_url,
  image_url
FROM public.universities
ORDER BY id;

