  r.uid, 'QS', 'QS Quacquarelli Symonds', 'QS World University Rankings',
  r.qs_r, r.qs_r, '#' || r.qs_r, 2026, 2026,
  'https://www.topuniversities.com/qs-world-university-rankings/methodology',
  'https://www.topuniversities.com/world-university-rankings',
  true, TIMESTAMP '2026-10-17 00:00:00', 'verified'
FROM ranks r
UNION ALL
SELECT
  r.uid, 'THE', 'Times Higher Education', 'THE World University Rankings',
  r.the_r, r.the_r, '#' || r.the_r, 2026, 2026,
  'https://www.timeshighereducation.com/world-university-rankings/methodology',
  'https://www.timeshighereducation.com/world-university-rankings',
  true, TIMESTAMP '2026-10-17 00:00:00', 'verified'
FROM ranks r
UNION ALL
SELECT
  r.uid, 'US_NEWS', 'U.S. News & World Report', 'U.S. News Best Global Universities',
  r.us_r, r.us_r, '#' || r.us_r, 2026, 2026,
  'https://www.usnews.com/education/best-global-universities/articles/methodology',
  'https://www.usnews.com/education/best-global-universities/rankings',
  true, TIMESTAMP '2026-10-17 00:00:00', 'verified'
FROM ranks r
ON CONFLICT (university_id, ranking_provider, ranking_name, ranking_year) DO UPDATE SET
  ranking_system = EXCLUDED.ranking_system,
  rank = EXCLUDED.rank,
  rank_numeric = EXCLUDED.rank_numeric,
  rank_display = EXCLUDED.rank_display,
  year = EXCLUDED.year,
  methodology_url = EXCLUDED.methodology_url,
  source_url = EXCLUDED.source_url,
  is_verified = true,
  last_verified_at = EXCLUDED.last_verified_at,
  verification_status = 'verified';

SELECT
  (SELECT COUNT(*) FROM public.universities) AS unis,
  (SELECT COUNT(*) FROM public.university_images) AS imgs,
  (SELECT COUNT(*) FROM public.campuses) AS camps,
  (SELECT COUNT(*) FROM public.university_rankings) AS ranks;
