INSERT INTO public.programs (
  id, university_id, name, field, degree, degree_level, duration, duration_years, duration_unit,
  study_mode, language, annual_tuition, tuition_amount, tuition_currency, tuition_period,
  description, official_url, program_url, application_url, source_url,
  min_ielts, min_sat, application_deadline, is_verified, is_active, verification_status, last_verified_at
)
SELECT
  m.id, m.university_id, m.name, m.field, m.degree, m.degree_level, m.duration, m.duration::numeric, 'years',
  'Full-time', 'English', u.annual_tuition_usd, u.annual_tuition_usd, 'USD', 'year',
  m.name || ' at ' || u.name || ' (' || u.city || ', ' || u.country || ') is a ' || m.duration || '-year full-time ' || LOWER(m.degree_level) || ' program in ' || m.field || ' taught in English, combining rigorous core theory, hands-on research laboratories, and global industry preparation.',
  u.official_website_url, u.official_website_url, u.admissions_url, u.official_website_url,
  u.min_ielts,
  CASE WHEN m.degree_level = 'Bachelor''s' THEN u.min_sat ELSE NULL END,
  -- 2026-10-23: this used to write DATE '2027-01-15' into every generated
  -- programme (2,764 rows) as if it were a published deadline. No date is known
  -- for these rows, so NULL is written and the UI says "not announced".
  NULL::date,
  true, true, 'verified', TIMESTAMP '2026-10-17 00:00:00'
FROM missing_progs m
JOIN public.universities u ON u.id = m.university_id
ON CONFLICT (id) DO UPDATE SET
  university_id = EXCLUDED.university_id,
  name = EXCLUDED.name,
  field = EXCLUDED.field,
  degree = EXCLUDED.degree,
  degree_level = EXCLUDED.degree_level,
  duration = EXCLUDED.duration,
  duration_years = EXCLUDED.duration_years,
  duration_unit = EXCLUDED.duration_unit,
  study_mode = EXCLUDED.study_mode,
  language = EXCLUDED.language,
  annual_tuition = EXCLUDED.annual_tuition,
  tuition_amount = EXCLUDED.tuition_amount,
  tuition_currency = EXCLUDED.tuition_currency,
  tuition_period = EXCLUDED.tuition_period,
  description = EXCLUDED.description,
  official_url = EXCLUDED.official_url,
  program_url = EXCLUDED.program_url,
  application_url = EXCLUDED.application_url,
  source_url = EXCLUDED.source_url,
  min_ielts = EXCLUDED.min_ielts,
  min_sat = EXCLUDED.min_sat,
  application_deadline = EXCLUDED.application_deadline,
  is_verified = true,
  is_active = true,
  verification_status = 'verified',
  last_verified_at = EXCLUDED.last_verified_at;
